def get_total_number_of_sequences(m, n):
	T=[[0 for _ in range(n + 1)] for _ in range(m + 1)] 
	for i in range(m + 1): 
		for j in range(n + 1): 
			if i==0 or j==0: 
				T[i][j] = 0
			elif i<j: 
				T[i][j] = 0
			elif j==1: 
